    bailey:{name:'Bailey',role:'Pictures and magic',src:illustratedFriends.bailey,tip:{home:'I’ve got lots of sparkly ideas! Want to choose a picture?',story:'Pictures and gestures make stories too. Let’s add something magical.',picture:'Choose a picture! We can move it together.',movie:'Time for some movie magic!',book:'A story looks wonderful with colourful pictures.',library:'Let’s find a story with a funny surprise.',classic:'Let’s explore our book again.'}},
