  let selectedHelper='kyle';try{const saved=localStorage.getItem(helperChoiceKey);if(helperChoices[saved])selectedHelper=saved;}catch(_){}
  const helperShelf=document.createElement('section');helperShelf.className='u-helper-shelf';helperShelf.setAttribute('aria-label','Choose your story helper');
  helperShelf.innerHTML='<h2>Meet your story helpers</h2><p>Pick a friend to help you. You can change your mind anytime.</p><div class="u-helper-cards" id="u-helper-cards"></div>';
