  function renderHelperCards(){const shelf=$('u-helper-cards');shelf.replaceChildren();for(const [key,helper] of Object.entries(helperChoices)){
     const b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Choose '+helper.name+' as your helper');b.setAttribute('aria-pressed',String(selectedHelper===key));
     const img=document.createElement('img');img.src=helper.src||art.kyle;img.alt='';const name=document.createElement('strong');name.textContent=helper.name;
     const desc=document.createElement('small');desc.textContent=helper.role;b.append(img,name,desc);b.onclick=()=>chooseHelper(key);shelf.append(b);
  }}
  function chooseHelper(key){if(!helperChoices[key])return;selectedHelper=key;try{localStorage.setItem(helperChoiceKey,key);}catch(_){}
    const helper=helperChoices[key];$('lic-kyle-avatar').src=helper.src||art.kyle;
    $('lic-kyle-toggle').setAttribute('aria-label','Ask '+helper.name+' for help');
    const text=$('lic-kyle-toggle').lastChild;if(text&&text.nodeType===3)text.nodeValue=' Ask '+helper.name;
    $('lic-kyle-panel').setAttribute('aria-label','Help from '+helper.name);
    kyle.querySelector('.kyle-head h2').textContent=helper.name+' can help!';
    $('lic-kyle-read').textContent='Hear '+helper.name+' explain';
    kyle.setAttribute('aria-label',helper.name+' site helper');
    renderHelperCards();refreshKyle();
  }
  renderHelperCards();
  function kyleLocation(){if(hub.hidden)return 'classic';if(!$('u-welcome').hidden)return 'home';if(!$('u-library').hidden)return 'library';return currentTab;}
  function refreshKyle(){const place=kyleLocation(),info=kyleTips[place];$('lic-kyle-tip').textContent=helperChoices[selectedHelper]?.tip[place]||info.message;
    const actions=$('lic-kyle-choices');actions.replaceChildren();for(const [label,action] of info.choices){const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.kyleAction=action;actions.append(button);}}
  function closeKyle(){if($('lic-kyle-panel').hidden)return;$('lic-kyle-panel').hidden=true;$('lic-kyle-toggle').setAttribute('aria-expanded','false');$('lic-kyle-toggle').focus({preventScroll:true});}
  $('lic-kyle-toggle').addEventListener('click',()=>{const panel=$('lic-kyle-panel');const opening=panel.hidden;panel.hidden=!opening;$('lic-kyle-toggle').setAttribute('aria-expanded',String(opening));if(opening){refreshKyle();$('lic-kyle-close').focus({preventScroll:true});}});
  $('lic-kyle-close').addEventListener('click',closeKyle);
  kyle.addEventListener('keydown',e=>{if(e.key==='Escape'){closeKyle();e.stopPropagation();}});
  function refreshVoices(){const voices=('speechSynthesis' in window?speechSynthesis.getVoices():[])||[];for(const sel of [$('lic-kyle-voice'),$('u-quick-voice')]){const old=sel.value;sel.replaceChildren();const def=document.createElement('option');def.value='';def.textContent='Device voice';sel.append(def);for(const v of voices){if(!/^(en|en-)/i.test(v.lang))continue;const option=document.createElement('option');option.value=v.voiceURI;option.textContent=`${v.name} (${v.lang})`;sel.append(option);}sel.value=[...sel.options].some(o=>o.value===old)?old:'';}}
  refreshVoices();if('speechSynthesis' in window)speechSynthesis.addEventListener?.('voiceschanged',refreshVoices);
  $('lic-kyle-read').onclick=()=>{if(!say($('lic-kyle-tip').textContent,true))$('lic-kyle-tip').textContent+=' This device cannot speak text aloud right now.';};
  $('u-quick-read').onclick=()=>{if(speaking){stopVoice();return;}if(!say(current()?.text||'Once upon a time, a new magical story was about to begin!'))status('This device cannot read aloud right now.');};
  $('lic-kyle-choices').addEventListener('click',e=>{const action=e.target.closest('[data-kyle-action]')?.dataset.kyleAction;if(!action)return;closeKyle();
    const guideTo=tab=>{if(!active)newProject();selectTab(tab);};
    if(action==='start')newProject();else if(action==='library'){show('library');drawLibrary();}else if(action==='return')returnToWorkspace();else if(action==='back-library'){returnToWorkspace();show('library');drawLibrary();}
    else if(action==='find-books')$('u-library-list').scrollIntoView({behavior:'smooth',block:'start'});
    else if(action==='examples'){showStarterHelp();}
     else if(action==='starter'){guideTo('story');$('u-generate').focus();$('u-generate').scrollIntoView({behavior:'smooth',block:'center'});}
    else if(action==='words'){guideTo('story');$('u-words').focus({preventScroll:true});$('u-words').scrollIntoView({behavior:'smooth',block:'center'});}
    else if(action==='pick-picture'){guideTo('picture');$('u-pic-hero').focus({preventScroll:true});}
    else if(action==='upload'){guideTo('picture');$('u-upload').focus({preventScroll:true});}
    else if(action==='voice'){$('lic-kyle-toggle').click();$('lic-kyle-voice').focus();}
    else if(action==='play'){guideTo('movie');$('u-play-movie').click();}
    else if(action==='read'){guideTo('book');$('u-read').click();}
    else if(action==='ebook'){guideTo('book');$('u-ebook').click();}
    else if(action==='print'){guideTo('book');$('u-print').click();}
    else if(['story','picture','movie','book'].includes(action)){guideTo(action);}
  });
  function show(which){$('u-welcome').hidden=which!=='home';$('u-work').hidden=which!=='work';$('u-library').hidden=which!=='library';if(which!=='work'){stopMovie();stopVoice();}refreshKyle();window.scrollTo({top:0,behavior:'instant'});}
  function useClassic(selector){stopMovie();stopVoice();hub.hidden=true;body.classList.remove('lic-unified-mode');refreshKyle();const el=selector?$(selector):document.querySelector('main#top');if(el)requestAnimationFrame(()=>el.scrollIntoView({block:'start',behavior:'instant'}));}
  function returnToWorkspace(){hub.hidden=false;body.classList.add('lic-unified-mode');show('work');selectTab('story');}
  returnButton.onclick=returnToWorkspace;$('u-old-site').onclick=()=>useClassic(null);$('u-old-drawing').onclick=()=>useClassic('lic-easy-art');
  $('u-home').onclick=()=>{flush();show('home');};$('u-library-jump').onclick=()=>{flush();show('library');toggleStarterGallery(true);drawLibrary();};$('u-start').onclick=()=>newProject();$('u-my-books').onclick=()=>{show('library');drawLibrary();};
  let classicLimit=48;
  function drawPalette(type){paletteKind=type;$('u-palette').hidden=false;$('u-palette-filters').hidden=type!=='all';
    if(type==='all'){classicLimit=48;$('u-palette-search').value='';$('u-palette-category').value='';}
    displayPalette();}
  function displayPalette(){const type=paletteKind,grid=$('u-palette-grid');grid.replaceChildren();let list=type==='friends'?friends:type==='worlds'?worlds:type==='all'?classicPieces:magicPieces;
     if(type==='friends')list=list.filter(v=>Boolean(illustratedFriends[v.id]||art[v.id]));
     if(type==='worlds')list=list.filter(v=>Boolean(illustratedWorlds[v.id]));
    if(type==='all'){const term=$('u-palette-search').value.trim().toLowerCase(),category=$('u-palette-category').value;
      list=list.filter(v=>(!category||v.group===category)&&(!term||(v.name+' '+v.group).toLowerCase().includes(term)));}
    if(type==='magic')list=list.filter(v=>!!cuteStickerArt[v.id]);
    const shown=type==='all'?list.slice(0,classicLimit):list;
    $('u-palette-results').textContent=type==='all'?`${list.length} matching inspiration prompts. These are story ideas, not illustrated images. Showing ${shown.length}.`:`${shown.length} colourful choices`;
    $('u-show-more-pieces').hidden=type!=='all'||shown.length===list.length;
    shown.forEach(v=>{const tile=document.createElement('div');tile.className='u-palette-tile';const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',(type==='magic'||type==='all'?'Add ':'Choose ')+v.name);const pic=art[v.id];if(type==='magic'&&cuteStickerArt[v.id]){const im=new Image();im.src=cuteStickerArt[v.id];im.alt='';im.className='u-sticker-thumb';b.append(im);}else if(type==='worlds'&&illustratedWorlds[v.id]){const im=new Image();im.src=illustratedWorlds[v.id];im.alt='';im.className='u-world-thumb';b.append(im);}else if(type==='friends'&&(illustratedFriends[v.id]||pic)){const im=new Image();im.src=illustratedFriends[v.id]||pic;im.alt='';b.append(im);}else if(type!=='all'){const face=document.createElement('span');face.className='u-tiny';face.textContent=v.emoji;b.append(face);}const label=document.createElement('span');label.textContent=v.name;b.append(label);
      if(type==='friends'&&v.id!=='me'){const add=document.createElement('button');add.type='button';add.className='u-add-friend';add.textContent='➕ Add friend to page';add.setAttribute('aria-label','Add '+v.name+' as a movable picture');add.onclick=event=>{event.stopPropagation();const p=current();if(p.elements.length>=40){status('This page already has 40 extra picture pieces.');return;}const piece={id:id(),friendId:v.id,emoji:v.emoji,name:v.name,x:.25+Math.random()*.4,y:.3+Math.random()*.35,size:.65,rotate:0};p.elements.push(piece);selectedPiece=piece.id;sceneCache.clear();persist();renderAll(false);status('✨ '+v.name+' joined the picture! Drag to move or resize.');};tile.append(add);}
       b.onclick=()=>{const p=current();if(type==='friends'){p.hero=v.id;active.hero=v.id;$('u-hero').value=v.id;$('u-pic-hero').value=v.id;p.mainX=.5;p.mainY=.5;p.mainSize=1;selectedPiece='main';}
        else if(type==='worlds'){p.world=v.id;active.world=v.id;$('u-world').value=v.id;$('u-pic-world').value=v.id;selectedPiece=null;}
        else if(type==='all'){const idea=v.name;const line='What if our story had '+idea.toLowerCase()+'?';p.text=((p.text||'').trim()+'\n'+line).trim();$('u-words').value=p.text;persist();renderAll(false);status('💡 Added '+idea+' as a story idea! Write about it or change the words.');return;}else{if(p.elements.length>=40){status('This page can have 40 extra picture pieces.');return;}const e={id:id(),emoji:v.emoji,name:v.name,artId:type==='magic'?v.id:null,x:.32+Math.random()*.3,y:.28+Math.random()*.3,size:1,rotate:0};p.elements.push(e);selectedPiece=e.id;}
        sceneCache.clear();persist();renderAll(false);showPieceTools();status(type==='magic'||type==='all'?`✨ ${v.name} added! Drag it on the picture to move it.`:`💜 ${v.name} chosen!`);};tile.prepend(b);grid.append(tile);});}
  $('u-palette-search').addEventListener('input',()=>{classicLimit=48;displayPalette();});
  $('u-palette-category').addEventListener('change',()=>{classicLimit=48;displayPalette();});
  $('u-show-more-pieces').onclick=()=>{classicLimit+=48;displayPalette();};
  function showPieceTools(){const p=current(),e=p?.elements?.find(x=>x.id===selectedPiece);$('u-sticker-tools').hidden=!(e||selectedPiece==='main');$('u-sticker-name').textContent=e?(e.src?'📷 Change your uploaded picture':`✨ ${e.name||e.emoji} — change this piece`):'🦊 Change the main friend';}
  function refreshLiveBook(){if(!active)return;const p=current();$('u-book-live-title').textContent=active.title||'My magical adventure';$('u-book-live-words').textContent=p.text||'Once upon a time… Your words go here!';
    const token=++livePreviewToken,c=$('u-book-live-canvas');getScene(p).then(scene=>{if(token!==livePreviewToken)return;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(scene,0,0,c.width,c.height);if($('u-palette').hidden||!selectedPiece)return;
      const piece=p.elements.find(x=>x.id===selectedPiece),x=piece?piece.x:p.mainX,y=piece?piece.y:p.mainY,size=piece?piece.size:p.mainSize;
      ctx.save();ctx.setLineDash([12,8]);ctx.strokeStyle='#6d31a9';ctx.lineWidth=6;ctx.strokeRect(x*c.width-100*size,y*c.height-100*size,200*size,200*size);ctx.restore();});}
  const live=$('u-book-live-canvas');let drag=null;
  function livePoint(ev){const rect=live.getBoundingClientRect();return{x:Math.max(.02,Math.min(.98,(ev.clientX-rect.left)/rect.width)),y:Math.max(.02,Math.min(.98,(ev.clientY-rect.top)/rect.height))};}
  live.addEventListener('pointerdown',ev=>{if(!active)return;const p=current(),pt=livePoint(ev);let nearest='main',dist=Math.hypot(pt.x-(p.mainX??.5),pt.y-(p.mainY??.5));for(const e of p.elements){const d=Math.hypot(pt.x-e.x,pt.y-e.y);if(d<dist){nearest=e.id;dist=d;}}if(dist>.32)return;selectedPiece=nearest;drag=ev.pointerId;try{live.setPointerCapture(ev.pointerId);}catch(_){}$('u-palette').hidden=false;showPieceTools();refreshLiveBook();ev.preventDefault();});
  live.addEventListener('pointermove',ev=>{if(drag!==ev.pointerId||!active)return;const p=current(),pt=livePoint(ev);if(selectedPiece==='main'){p.mainX=pt.x;p.mainY=pt.y;}else{const e=p.elements.find(x=>x.id===selectedPiece);if(e){e.x=pt.x;e.y=pt.y;}}sceneCache.clear();refreshLiveBook();schedule();ev.preventDefault();});
  const endDrag=ev=>{if(drag===ev.pointerId){drag=null;persist();}};live.addEventListener('pointerup',endDrag);live.addEventListener('pointercancel',endDrag);
  for(const [name,kind] of [['u-quick-characters','friends'],['u-quick-places','worlds'],['u-quick-magic','magic'],['u-quick-600','all']])$(name).onclick=()=>{drawPalette(kind);$('u-palette').scrollIntoView({behavior:'smooth',block:'nearest'});};
  for(const b of hub.querySelectorAll('[data-palette]'))b.addEventListener('click',()=>drawPalette(b.dataset.palette));
  $('u-palette-close').onclick=()=>{$('u-palette').hidden=true;selectedPiece=null;refreshLiveBook();};
  $('u-piece-upload').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const src=await uploadData(file);const p=current();if(p.elements.length>=40)throw Error('This page already has 40 extra pieces.');const layer={id:id(),emoji:'📷',src,x:.5,y:.5,size:1,rotate:0};p.elements.push(layer);selectedPiece=layer.id;sceneCache.clear();persist();showPieceTools();renderAll(false);status('📷 Your drawing is now a movable piece! Drag it on the book.');}catch(err){status(err.message);}e.target.value='';};
  function mutatePiece(op){if(!active||!selectedPiece)return;const p=current(),e=p.elements.find(x=>x.id===selectedPiece);if(op==='remove'){if(e)p.elements=p.elements.filter(x=>x.id!==e.id);else if(selectedPiece==='main'){status('Choose a different friend from the palette.');return;}selectedPiece=null;}
    else if(e){if(op==='bigger')e.size=Math.min(2.8,e.size*1.2);else if(op==='smaller')e.size=Math.max(.3,e.size/1.2);else if(op==='turn')e.rotate=(e.rotate+25)%360;}
    else if(selectedPiece==='main'){if(op==='bigger')p.mainSize=Math.min(2.5,(p.mainSize||1)*1.2);else if(op==='smaller')p.mainSize=Math.max(.35,(p.mainSize||1)/1.2);}
    sceneCache.clear();persist();showPieceTools();renderAll(false);}
  for(const [control,act] of [['u-piece-bigger','bigger'],['u-piece-smaller','smaller'],['u-piece-turn','turn'],['u-piece-remove','remove']])$(control).onclick=()=>mutatePiece(act);
  function newProject(){stopMovie();stopVoice();flush();active={id:id(),title:'My Magical Adventure',hero:'kyle',world:'castle',quest:'key',heroName:'',pages:[mkPage()]};pageIndex=0;persist();show('work');selectTab('story',false);renderAll();}
  function flush(){if(!active)return;const p=active.pages[pageIndex];if(!p)return;active.title=$('u-title').value.trim().slice(0,85)||active.title;
    if(currentTab==='story')p.text=$('u-words').value.slice(0,2200);}
  function activate(project){stopMovie();stopVoice();flush();active=normalize(project);pageIndex=0;show('work');selectTab('story',false);renderAll();}
  function current(){return active?.pages?.[pageIndex];}
  function selectTab(tab,commit=true){if(active&&commit)flush();stopMovie();stopVoice();currentTab=tab;refreshKyle();for(const name of ['story','picture','movie','book']){$('u-panel-'+name).hidden=name!==tab;$('u-tab-'+name).setAttribute('aria-selected',String(name===tab));}renderAll(false);}
  for(const b of hub.querySelectorAll('[data-u-tab]'))b.addEventListener('click',()=>selectTab(b.dataset.uTab));
  function renderAll(rewrite=true){if(!active)return;const p=current();$('u-title').value=active.title;$('u-count').textContent=`Page ${pageIndex+1} of ${active.pages.length}`;
    $('u-prev').disabled=pageIndex===0;$('u-next').disabled=pageIndex>=active.pages.length-1;
    if(rewrite){$('u-hero').value=active.hero;$('u-world').value=active.world;$('u-adventure').value=active.quest;$('u-hero-name').value=active.heroName||'';$('u-hero-name-box').hidden=active.hero!=='me';$('u-words').value=p.text||'';}
    $('u-pic-hero').value=p.hero;$('u-pic-world').value=p.world;$('u-remove-picture').disabled=!p.photo;
    $('u-reader-title').textContent=active.title;$('u-book-words').textContent=p.text||'Your story words go here!';
    $('u-remove-page').disabled=active.pages.length<=1;
    refreshLiveBook();showPieceTools();syncRails();if(currentTab==='picture')renderCanvas($('u-picture-canvas'),p);
    if(currentTab==='book')renderCanvas($('u-book-canvas'),p);
    if(currentTab==='movie')renderMovieStill();
    v4sync();
  }
  function movePage(delta){flush();pageIndex=Math.max(0,Math.min(active.pages.length-1,pageIndex+delta));schedule();renderAll();stopVoice();}
  $('u-prev').onclick=()=>movePage(-1);$('u-next').onclick=()=>movePage(1);
  $('u-title').addEventListener('input',e=>{if(!active)return;active.title=e.target.value.slice(0,85);$('u-reader-title').textContent=active.title;refreshLiveBook();schedule();});
  $('u-words').addEventListener('input',e=>{if(!current())return;current().text=e.target.value;$('u-book-words').textContent=e.target.value;refreshLiveBook();schedule();});
  function globalChange(){if(!active)return;active.hero=$('u-hero').value;active.world=$('u-world').value;active.quest=$('u-adventure').value;active.heroName=$('u-hero-name').value.slice(0,40);
    $('u-hero-name-box').hidden=active.hero!=='me';const p=current();if(p&&!p.photo){p.hero=active.hero;p.world=active.world;}sceneCache.clear();refreshLiveBook();schedule();}
  for(const name of ['u-hero','u-world','u-adventure','u-hero-name'])$(name).addEventListener('change',globalChange);
  $('u-add-page').onclick=()=>{flush();if(active.pages.length>=20){status('A book can have up to 20 pages.');return;}active.pages.splice(pageIndex+1,0,mkPage(active.hero,active.world));pageIndex++;persist();renderAll();$('u-words').focus();};
  $('u-remove-page').onclick=()=>{if(active.pages.length<=1)return;if(!confirm('Remove this page from your story?'))return;active.pages.splice(pageIndex,1);pageIndex=Math.max(0,Math.min(pageIndex,active.pages.length-1));persist();renderAll();};
