  function storyText(){const hero=active.hero==='me'?(active.heroName.trim()||'Our little hero'):(friendBy[active.hero]?.name||'King Kyle');const place=(worldBy[active.world]?.name||'magical kingdom').toLowerCase();
    const q={key:['a little golden key','Nobody knew what the key would open.','A tiny door hidden in the flowers','Inside, they discovered a room full of wonderful pictures.'],lost:['a worried little friend','The friend could not find the way home.','They followed soft footprints through the trees','Together, they found the way home and shared a big hug.'],star:['a fallen sparkling star','The star needed to get back into the night sky.','They made a ladder of silver moonbeams','The little star flew up and twinkled thank you.'],party:['a secret party invitation','Nobody knew who the party was for.','They gathered lanterns, balloons and their friends','Surprise! The party was for the whole kingdom.'],bridge:['a broken bridge','Some tiny animals were stranded across the river.','They collected safe wooden planks and worked together','The animals crossed safely and everybody cheered.'],wish:['a glowing wish stone','It could grant just one wish.','They listened carefully to what their friends needed','They wished that nobody in the kingdom would feel alone.'],treasure:['a map covered in sparkles','An X marked a secret hiding place.','The friends searched through winding pathways','They found a chest filled with friendship bracelets and shared them with everyone.'],pet:['a tiny animal looking for a home','The little creature needed kindness and care.','They built a cosy place and brought fresh water','The creature curled up happily beside its new friends.'],balloon:['a rainbow balloon that could float above the clouds','A sudden breeze carried it very high!','They followed the balloon on a funny journey','With a little teamwork, the balloon floated safely back home.'],rainbow:['a rainbow missing all its colours','Without colour the sky seemed rather sleepy.','They gathered pink flowers, golden sunshine and blue ocean light','The rainbow sparkled again and the whole world danced.'],castleparty:['a sparkly invitation from the castle','No one knew who would arrive at the royal party.','They hung twinkly lights and prepared delicious treats','Everyone arrived together and the happiest royal party began.'],gardenparty:['a letter from the garden flowers','The flowers wanted to throw a party for their friends.','They collected ribbons and tiny cakes','The garden filled with music, laughter and wonderful new friendships.']}[active.quest]||[];
    return [`One bright morning, ${hero} set off into the ${place}. It felt like the beginning of something extraordinary.`,
     `On the path, ${hero} found ${q[0]}. What a surprising discovery!`,
     `${q[1]} ${hero} wondered how to help. This was going to be a real adventure.`,
     `${q[2]}. ${hero} was brave, but remembered that asking friends for help could be brave too.`,
     `${q[3]} ${hero} smiled. What wonderful magic friendship can make! The end. 💜`];
  }
  $('u-generate').onclick=()=>{globalChange();flush();if(active.pages.some(p=>p.text.trim())&&!confirm('Replace your current words with a new starter story?'))return;
    const old=active.pages.slice();active.pages=storyText().map((t,i)=>({...mkPage(active.hero,active.world,t),photo:old[i]?.photo||null,hero:old[i]?.hero||active.hero,world:old[i]?.world||active.world,elements:old[i]?.elements||[],mainX:old[i]?.mainX??.5,mainY:old[i]?.mainY??.5,mainSize:old[i]?.mainSize||1}));pageIndex=0;persist();renderAll();status('✨ Your story is ready! Change any words or add your own pages.');};
